import {SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY} from './supabase-config.mjs';
import {baselines} from './site-data-baselines.mjs';
import {applySourceValues,guideDerived} from './site-data-model.mjs';
const cache=new Map(),root=new URL('.',import.meta.url);
export function publishedData(key){if(!cache.has(key))cache.set(key,(async()=>{const abort=new AbortController(),timer=setTimeout(()=>abort.abort(),2500);try{const response=await fetch(SUPABASE_URL+'/rest/v1/rpc/published_site_data',{method:'POST',headers:{apikey:SUPABASE_PUBLISHABLE_KEY,'Content-Type':'application/json'},body:JSON.stringify({p_key:key}),signal:abort.signal});if(!response.ok)return null;const record=await response.json();return record&&record.baseline===baselines[key]?record:null;}catch{return null;}finally{clearTimeout(timer)}})());return cache.get(key);}
export async function loadAppData(){const response=await fetch(new URL('./data.json',root));if(!response.ok)throw Error('Event data unavailable');const base=await response.json(),record=await publishedData('schedule');if(record)try{return applySourceValues(base,record.values)}catch{}return base;}
export async function loadGuideData(key){const response=await fetch(new URL('./guide-data/'+key+'.json',root));if(!response.ok)throw Error('Guide data unavailable');let data=await response.json();if(['horde','spa-audit'].includes(key))return data;const record=await publishedData('guide:'+key);if(record)try{data=applySourceValues(data,record.values)}catch{}return guideDerived(key,data);}
